/**
 * One real task on /ai (#593): its GitHub events are pinned in
 * `task-timeline.json` (regenerated by `scripts/fetch-task-timeline.sh <pr>`)
 * and its phases derived by `lib/task-timeline.mjs`.
 */
import task from './task-timeline.json';
import { phases } from '../lib/task-timeline.mjs';

export const taskTimeline = task;
export const taskPhases = phases(task.events);
/** The day the task merged: the date its durations were measured. */
export const taskDate = task.events.at(-1)!.at.slice(0, 10);
